contracts/OKBONDICOV8.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.26;

/**
 * =========================================================
  *                 OKBOND ICO V8 FINAL
   * =========================================================
    * Production-Oriented ICO Contract
     *
      * FEATURES:
       * ✔ USDT ONLY
        * ✔ 3 ROUNDS
         * ✔ INSTANT CLAIM
          * ✔ NO REFUND MODEL
           * ✔ ANTI WHALE
            * ✔ HARD CAP
             * ✔ SOFT CAP TRACKING
              * ✔ LIQUIDITY SPLIT
               * ✔ TREASURY SPLIT
                * ✔ UNSOLD RETURN TO VAULT
                 * ✔ PAUSE SYSTEM
                  * ✔ TIMELOCK GOVERNANCE
                   * ✔ OZ V5 COMPATIBLE
                    * ✔ REENTRANCY PROTECTION
                     * ✔ EMERGENCY RECOVERY
                      * ✔ POLYGON READY
                       * =========================================================
                        */

                        import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
                        import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
                        import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

                        contract OKBOND_ICO_V8 is ReentrancyGuard {
                            using SafeERC20 for IERC20;

                                // =====================================================
                                    // CORE
                                        // =====================================================

                                            IERC20 public immutable okbond;
                                                IERC20 public immutable usdt;

                                                    address public immutable vault;
                                                        address public immutable treasury;

                                                            address public timelock;

                                                                bool public paused;
                                                                    bool public finalized;

                                                                        // =====================================================
                                                                            // ICO CONFIG
                                                                                // =====================================================

                                                                                    uint256 public constant TOTAL_ICO_TOKENS =
                                                                                            1_000_000 * 1e18;

                                                                                                // =====================================================
                                                                                                    // ROUND SUPPLY
                                                                                                        // =====================================================

                                                                                                            uint256 public constant ROUND1_SUPPLY =
                                                                                                                    333_333 * 1e18;

                                                                                                                        uint256 public constant ROUND2_SUPPLY =
                                                                                                                                333_333 * 1e18;

                                                                                                                                    uint256 public constant ROUND3_SUPPLY =
                                                                                                                                            333_334 * 1e18;

                                                                                                                                                // =====================================================
                                                                                                                                                    // ROUND PRICES
                                                                                                                                                        // =====================================================

                                                                                                                                                            // PRICE FORMAT:
                                                                                                                                                                // 50  = $0.50
                                                                                                                                                                    // 70  = $0.70
                                                                                                                                                                        // 100 = $1.00

                                                                                                                                                                            uint256 public constant ROUND1_PRICE = 50;
                                                                                                                                                                                uint256 public constant ROUND2_PRICE = 70;
                                                                                                                                                                                    uint256 public constant ROUND3_PRICE = 100;

                                                                                                                                                                                        // =====================================================
                                                                                                                                                                                            // BUY LIMITS
                                                                                                                                                                                                // =====================================================

                                                                                                                                                                                                    uint256 public constant MIN_BUY =
                                                                                                                                                                                                            10 * 1e18;

                                                                                                                                                                                                                uint256 public constant MAX_BUY =
                                                                                                                                                                                                                        2000 * 1e18;

                                                                                                                                                                                                                            // =====================================================
                                                                                                                                                                                                                                // FUND SPLIT
                                                                                                                                                                                                                                    // =====================================================

                                                                                                                                                                                                                                        uint256 public constant LIQUIDITY_PERCENT = 60;
                                                                                                                                                                                                                                            uint256 public constant TREASURY_PERCENT = 40;

                                                                                                                                                                                                                                                // =====================================================
                                                                                                                                                                                                                                                    // CAPS
                                                                                                                                                                                                                                                        // =====================================================

                                                                                                                                                                                                                                                            uint256 public softCapUSDT;
                                                                                                                                                                                                                                                                uint256 public hardCapUSDT;

                                                                                                                                                                                                                                                                    // =====================================================
                                                                                                                                                                                                                                                                        // ICO TIME
                                                                                                                                                                                                                                                                            // =====================================================

                                                                                                                                                                                                                                                                                uint256 public startTime;
                                                                                                                                                                                                                                                                                    uint256 public endTime;

                                                                                                                                                                                                                                                                                        // =====================================================
                                                                                                                                                                                                                                                                                            // GLOBAL STATS
                                                                                                                                                                                                                                                                                                // =====================================================

                                                                                                                                                                                                                                                                                                    uint256 public totalRaisedUSDT;
                                                                                                                                                                                                                                                                                                        uint256 public totalTokensSold;

                                                                                                                                                                                                                                                                                                            // =====================================================
                                                                                                                                                                                                                                                                                                                // USER DATA
                                                                                                                                                                                                                                                                                                                    // =====================================================

                                                                                                                                                                                                                                                                                                                        mapping(address => uint256)
                                                                                                                                                                                                                                                                                                                                public totalPurchased;

                                                                                                                                                                                                                                                                                                                                    mapping(address => uint256)
                                                                                                                                                                                                                                                                                                                                            public usdtContributed;

                                                                                                                                                                                                                                                                                                                                                // =====================================================
                                                                                                                                                                                                                                                                                                                                                    // ROUND SYSTEM
                                                                                                                                                                                                                                                                                                                                                        // =====================================================

                                                                                                                                                                                                                                                                                                                                                            enum Round {
                                                                                                                                                                                                                                                                                                                                                                    ROUND1,
                                                                                                                                                                                                                                                                                                                                                                            ROUND2,
                                                                                                                                                                                                                                                                                                                                                                                    ROUND3,
                                                                                                                                                                                                                                                                                                                                                                                            ENDED
                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                    Round public currentRound;

                                                                                                                                                                                                                                                                                                                                                                                                        uint256 public round1Sold;
                                                                                                                                                                                                                                                                                                                                                                                                            uint256 public round2Sold;
                                                                                                                                                                                                                                                                                                                                                                                                                uint256 public round3Sold;

                                                                                                                                                                                                                                                                                                                                                                                                                    // =====================================================
                                                                                                                                                                                                                                                                                                                                                                                                                        // EVENTS
                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                event TokensPurchased(
                                                                                                                                                                                                                                                                                                                                                                                                                                        address indexed buyer,
                                                                                                                                                                                                                                                                                                                                                                                                                                                uint256 usdtSpent,
                                                                                                                                                                                                                                                                                                                                                                                                                                                        uint256 tokensReceived
                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                event ICOFinalized(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        uint256 liquidityFunds,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                uint256 treasuryFunds,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        uint256 unsoldReturned
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                event EmergencyPause(bool status);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    event Recovered(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            address token,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    uint256 amount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // =====================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // MODIFIERS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        modifier onlyTimelock() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            msg.sender == timelock,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Not timelock"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        _;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                modifier notPaused() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    !paused,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "ICO paused"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                _;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        modifier saleActive() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            block.timestamp >= startTime,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "ICO not started"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    block.timestamp <= endTime,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "ICO ended"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            !finalized,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Already finalized"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        _;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // CONSTRUCTOR
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            constructor(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    address _okbond,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            address _usdt,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    address _vault,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            address _treasury,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    address _timelock,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            uint256 _softCapUSDT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    uint256 _hardCapUSDT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            uint256 _startTime,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    uint256 _endTime
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            _okbond != address(0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Invalid OKBOND"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    _usdt != address(0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Invalid USDT"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            _vault != address(0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Invalid vault"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    _treasury != address(0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Invalid treasury"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            _timelock != address(0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Invalid timelock"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    _startTime < _endTime,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Invalid time"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            _softCapUSDT < _hardCapUSDT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Invalid caps"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        okbond = IERC20(_okbond);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                usdt = IERC20(_usdt);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        vault = _vault;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                treasury = _treasury;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        timelock = _timelock;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                softCapUSDT = _softCapUSDT;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        hardCapUSDT = _hardCapUSDT;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                startTime = _startTime;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        endTime = _endTime;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                currentRound = Round.ROUND1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // =====================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // BUY TOKENS
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // =====================================================

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    function buy(uint256 usdtAmount)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            external
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    nonReentrant
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            notPaused
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    saleActive
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            currentRound != Round.ENDED,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "ICO ended"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    usdtAmount > 0,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                "Invalid amount"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            totalRaisedUSDT + usdtAmount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            <= hardCapUSDT,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Hardcap reached"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        uint256 tokensToReceive =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    calculateTokens(usdtAmount);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tokensToReceive >= MIN_BUY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Min 10 OKBOND"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    require(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                totalPurchased[msg.sender] +
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                tokensToReceive <=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                MAX_BUY,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            "Max 2000 OKBOND"
